<?php
namespace ZinCelestial\Platform\Governance;use RuntimeException;defined('ABSPATH')||exit;
final class GovernanceEngine{private array $policies=[];public function register(GovernancePolicy $p):void{$this->policies[$p->id()]=$p;}public function decide(string $policy,string $operation,array $approvals,int $requester,int $site):GovernanceDecision{$id=sanitize_key($policy);$op=sanitize_key($operation);$p=$this->policies[$id]??null;if(!$p||$p->operation()!==$op)throw new RuntimeException('Governance policy denied operation.');$valid=$p->evaluate($approvals,$requester);$actors=[];foreach($approvals as $a){$x=(int)($a['actor']??0);if($x>0)$actors[$x]=true;}$decision=new GovernanceDecision(wp_generate_uuid4(),$site,$id,$op,$valid?'allow':'deny',$requester,array_keys($actors),time());if(!$valid)throw new RuntimeException('Governance policy denied operation.');return$decision;}}
